//! Converts the root README.md (the project's single source of truth) into
//! roff man-page sections. The CLI reference (NAME, SYNOPSIS, OPTIONS,
//! VERSION) is generated by `clap_mangen` in `build.rs`; this module supplies
//! the prose from the README.
use std::fmt::Write as _;

#[derive(Debug, Clone, PartialEq)]
enum Block {
    Heading {
        level: usize,
        text: String,
    },
    Paragraph(Vec<String>),
    BulletList(Vec<BulletItem>),
    OrderedList(Vec<String>),
    Code(String),
    Table {
        headers: Vec<String>,
        rows: Vec<Vec<String>>,
    },
    Rule,
}

#[derive(Debug, Clone, PartialEq)]
struct BulletItem {
    text: String,
    nested: Vec<BulletItem>,
}

#[derive(Debug, Clone, PartialEq)]
enum Span {
    Text(String),
    Code(String),
    Bold(String),
    Italic(String),
    Link { text: String },
}

pub fn description(readme: &str) -> String {
    let blocks = parse(readme);
    let quick_start = find_heading(&blocks, 2, "quick start");
    let dependencies = find_heading(&blocks, 2, "dependencies");
    let mut out = String::new();
    render(&mut out, &blocks[1..quick_start]);
    render(&mut out, &blocks[quick_start + 1..dependencies]);
    out
}

pub fn body(readme: &str) -> String {
    let blocks = parse(readme);
    let dependencies = find_heading(&blocks, 2, "dependencies");
    let table_of_contents = find_heading(&blocks, 2, "table of contents");
    let concepts = find_heading(&blocks, 2, "concepts");
    let mut out = String::new();
    // The table of contents is meaningless on a man page, so it is dropped.
    render(&mut out, &blocks[dependencies..table_of_contents]);
    render(&mut out, &blocks[concepts..]);
    out
}

fn find_heading(blocks: &[Block], level: usize, key: &str) -> usize {
    blocks
        .iter()
        .position(|block| match block {
            Block::Heading { level: found, text } => {
                *found == level && normalize_heading(text) == key
            }
            _ => false,
        })
        .unwrap_or_else(|| panic!("README.md has no {level}-level heading \"{key}\""))
}

fn normalize_heading(text: &str) -> String {
    strip_section_number(text).trim().to_lowercase()
}

fn parse(readme: &str) -> Vec<Block> {
    let lines: Vec<&str> = readme.lines().collect();
    let mut blocks = Vec::new();
    let mut index = 0;
    while index < lines.len() {
        let raw = lines[index];
        let line = raw.trim();
        if line.is_empty() {
            index += 1;
            continue;
        }
        if line == "---" {
            blocks.push(Block::Rule);
            index += 1;
            continue;
        }
        if line.starts_with('#') {
            let level = raw.bytes().take_while(|&byte| byte == b'#').count();
            let text = raw[level..].trim().to_string();
            blocks.push(Block::Heading { level, text });
            index += 1;
            continue;
        }
        if line.starts_with("```") {
            index += 1;
            let mut code = Vec::new();
            while index < lines.len() && lines[index].trim() != "```" {
                code.push(lines[index]);
                index += 1;
            }
            if index < lines.len() {
                index += 1;
            }
            blocks.push(Block::Code(trim_code_block(&code)));
            continue;
        }
        if line.starts_with('|') {
            let mut table_lines = Vec::new();
            while index < lines.len() && lines[index].trim_start().starts_with('|') {
                table_lines.push(lines[index].trim().to_string());
                index += 1;
            }
            blocks.push(parse_table(&table_lines));
            continue;
        }
        if ordered_marker(line).is_some() {
            let mut items = Vec::new();
            while index < lines.len() {
                match ordered_marker(lines[index].trim()) {
                    Some(item) => {
                        items.push(item.to_string());
                        index += 1;
                    }
                    None => break,
                }
            }
            blocks.push(Block::OrderedList(items));
            continue;
        }
        if bullet_indent(line).is_some() {
            let (items, next) = parse_bullets(&lines, index);
            blocks.push(Block::BulletList(items));
            index = next;
            continue;
        }
        let mut paragraph = Vec::new();
        while index < lines.len() {
            let trimmed = lines[index].trim();
            if trimmed.is_empty()
                || trimmed == "---"
                || trimmed.starts_with('#')
                || trimmed.starts_with("```")
                || trimmed.starts_with('|')
                || ordered_marker(trimmed).is_some()
                || bullet_indent(trimmed).is_some()
            {
                break;
            }
            paragraph.push(trimmed.to_string());
            index += 1;
        }
        blocks.push(Block::Paragraph(paragraph));
    }
    blocks
}

fn trim_code_block(lines: &[&str]) -> String {
    let start = lines
        .iter()
        .position(|line| !line.trim().is_empty())
        .unwrap_or(lines.len());
    let end = lines
        .iter()
        .rposition(|line| !line.trim().is_empty())
        .map_or(start, |position| position + 1);
    lines[start..end].join("\n")
}

fn parse_table(table_lines: &[String]) -> Block {
    let mut rows: Vec<Vec<String>> = Vec::new();
    for line in table_lines {
        let cells = split_table_line(line);
        if is_separator_row(&cells) {
            continue;
        }
        rows.push(cells);
    }
    let headers = rows.remove(0);
    Block::Table { headers, rows }
}

fn split_table_line(line: &str) -> Vec<String> {
    line.trim()
        .trim_start_matches('|')
        .trim_end_matches('|')
        .split('|')
        .map(|cell| cell.trim().to_string())
        .collect()
}

fn is_separator_row(cells: &[String]) -> bool {
    !cells.is_empty()
        && cells
            .iter()
            .all(|cell| !cell.is_empty() && cell.chars().all(|ch| ch == '-' || ch == ':'))
}

fn parse_bullets(lines: &[&str], start: usize) -> (Vec<BulletItem>, usize) {
    let mut entries: Vec<(usize, String)> = Vec::new();
    let mut index = start;
    while index < lines.len() {
        match bullet_indent(lines[index]) {
            Some(indent) => {
                entries.push((indent, bullet_text(lines[index])));
                index += 1;
            }
            None => break,
        }
    }
    let mut rest = entries.iter().peekable();
    let items = build_nested(&mut rest, -1);
    (items, index)
}

fn build_nested<'a>(
    entries: &mut std::iter::Peekable<impl Iterator<Item = &'a (usize, String)>>,
    parent_indent: isize,
) -> Vec<BulletItem> {
    let mut items = Vec::new();
    while let Some(&(indent, _)) = entries.peek() {
        if *indent as isize <= parent_indent {
            break;
        }
        let (_, text) = entries.next().expect("peeked");
        let mut item = BulletItem {
            text: text.clone(),
            nested: Vec::new(),
        };
        if let Some(&(next_indent, _)) = entries.peek()
            && *next_indent > *indent
        {
            item.nested = build_nested(entries, *indent as isize);
        }
        items.push(item);
    }
    items
}

fn bullet_indent(line: &str) -> Option<usize> {
    let trimmed = line.trim_start();
    let first = *trimmed.as_bytes().first()?;
    if first != b'-' && first != b'*' && first != b'+' {
        return None;
    }
    let rest = &trimmed[1..];
    if rest.is_empty() || rest.starts_with(' ') {
        Some(line.len() - trimmed.len())
    } else {
        None
    }
}

fn bullet_text(line: &str) -> String {
    line.trim_start()[1..].trim_start().to_string()
}

fn ordered_marker(line: &str) -> Option<&str> {
    let bytes = line.as_bytes();
    let mut index = 0;
    while index < bytes.len() && bytes[index].is_ascii_digit() {
        index += 1;
    }
    if index == 0 || index >= bytes.len() || (bytes[index] != b'.' && bytes[index] != b')') {
        return None;
    }
    let rest = &line[index + 1..];
    if rest.is_empty() || rest.starts_with(' ') {
        Some(rest.trim_start())
    } else {
        None
    }
}

fn strip_section_number(text: &str) -> &str {
    let bytes = text.as_bytes();
    let mut index = 0;
    while index < bytes.len() && bytes[index].is_ascii_digit() {
        index += 1;
    }
    if index == 0 {
        return text;
    }
    while index < bytes.len() && bytes[index] == b'.' {
        let mut sub = index + 1;
        if sub >= bytes.len() || !bytes[sub].is_ascii_digit() {
            return text;
        }
        while sub < bytes.len() && bytes[sub].is_ascii_digit() {
            sub += 1;
        }
        index = sub;
    }
    if index < bytes.len() && bytes[index].is_ascii_whitespace() {
        let rest = text[index..].trim_start();
        if !rest.is_empty() {
            return rest;
        }
    }
    text
}

fn render(out: &mut String, blocks: &[Block]) {
    for block in blocks {
        match block {
            Block::Heading { level, text } => render_heading(out, *level, text),
            Block::Paragraph(lines) => render_paragraph(out, lines),
            Block::BulletList(items) => render_bullets(out, items),
            Block::OrderedList(items) => render_ordered(out, items),
            Block::Code(code) => render_code(out, code),
            Block::Table { headers, rows } => render_table(out, headers, rows),
            Block::Rule => {}
        }
    }
}

fn render_heading(out: &mut String, level: usize, text: &str) {
    if level == 1 {
        return;
    }
    let macro_name = if level == 2 { "SH" } else { "SS" };
    let title = render_spans(&parse_spans(
        &strip_section_number(text).trim().to_uppercase(),
    ));
    let _ = writeln!(out, ".{macro_name} \"{title}\"");
}

fn render_paragraph(out: &mut String, lines: &[String]) {
    out.push_str(".PP\n");
    push_text_line(out, &lines.join(" "));
}

fn push_text_line(out: &mut String, text: &str) {
    let rendered = render_spans(&parse_spans(text));
    if rendered.starts_with('.') || rendered.starts_with('\'') {
        out.push_str("\\&");
    }
    out.push_str(&rendered);
    out.push('\n');
}

fn render_bullets(out: &mut String, items: &[BulletItem]) {
    for item in items {
        render_bullet(out, item, 0);
    }
}

fn render_bullet(out: &mut String, item: &BulletItem, depth: usize) {
    let _ = writeln!(out, ".IP \\(bu {}", 2 + depth * 2);
    push_text_line(out, &item.text);
    if !item.nested.is_empty() {
        out.push_str(".RS 4\n");
        for child in &item.nested {
            render_bullet(out, child, depth + 1);
        }
        out.push_str(".RE\n");
    }
}

fn render_ordered(out: &mut String, items: &[String]) {
    for (number, item) in items.iter().enumerate() {
        let _ = writeln!(out, ".IP \"{}\" 4", number + 1);
        push_text_line(out, item);
    }
}

fn render_code(out: &mut String, code: &str) {
    out.push_str(".RS 4\n.nf\n");
    for line in code.lines() {
        let escaped = line.replace('\\', r"\\");
        if escaped.starts_with('.') || escaped.starts_with('\'') {
            out.push_str("\\&");
        }
        out.push_str(&escaped);
        out.push('\n');
    }
    out.push_str(".fi\n.RE\n");
}

fn render_table(out: &mut String, headers: &[String], rows: &[Vec<String>]) {
    let column_count = headers.len();
    assert_ne!(column_count, 0, "a table must have a header row");
    out.push_str(".ad l\n.TS\nallbox tab(~);\n");
    let mut format = String::new();
    for _ in 0..column_count {
        format.push('l');
        format.push(' ');
    }
    format.pop();
    out.push_str(&format);
    out.push_str(".\n");
    push_table_row(out, headers);
    out.push_str("=\n");
    for row in rows {
        assert_eq!(
            row.len(),
            column_count,
            "a table row does not match the header column count"
        );
        push_table_row(out, row);
    }
    out.push_str(".\n.TE\n.ad\n");
}

fn push_table_row(out: &mut String, cells: &[String]) {
    for (index, cell) in cells.iter().enumerate() {
        let rendered = render_spans(&parse_spans(cell));
        assert!(
            !rendered.contains('~'),
            "a table cell must not contain '~': {rendered:?}"
        );
        if index > 0 {
            out.push('~');
        }
        out.push_str("T{\n");
        if rendered.starts_with('.') || rendered.starts_with('\'') {
            out.push_str("\\&");
        }
        out.push_str(&rendered);
        out.push_str("\nT}");
    }
    out.push('\n');
}

fn parse_spans(text: &str) -> Vec<Span> {
    let mut spans = Vec::new();
    let mut rest = text;
    while !rest.is_empty() {
        if let Some(after) = rest.strip_prefix('`') {
            match after.find('`') {
                Some(end) => {
                    spans.push(Span::Code(after[..end].to_string()));
                    rest = &after[end + 1..];
                }
                None => {
                    spans.push(Span::Text("`".to_string()));
                    rest = after;
                }
            }
            continue;
        }
        if let Some(after) = rest.strip_prefix("**") {
            match after.find("**") {
                Some(end) => {
                    spans.push(Span::Bold(after[..end].to_string()));
                    rest = &after[end + 2..];
                }
                None => {
                    spans.push(Span::Text("**".to_string()));
                    rest = after;
                }
            }
            continue;
        }
        if let Some(after) = rest.strip_prefix('*') {
            match after.find('*') {
                Some(end) => {
                    spans.push(Span::Italic(after[..end].to_string()));
                    rest = &after[end + 1..];
                }
                None => {
                    spans.push(Span::Text("*".to_string()));
                    rest = after;
                }
            }
            continue;
        }
        if let Some(after) = rest.strip_prefix('[') {
            let mut consumed = false;
            if let Some(open) = after.find("](")
                && let Some(close) = after[open + 2..].find(')')
            {
                spans.push(Span::Link {
                    text: after[..open].to_string(),
                });
                rest = &after[open + 2 + close + 1..];
                consumed = true;
            }
            if consumed {
                continue;
            }
        }
        let special = rest.find(['`', '*', '[']);
        match special {
            Some(0) => {
                spans.push(Span::Text(rest[..1].to_string()));
                rest = &rest[1..];
            }
            Some(position) => {
                spans.push(Span::Text(rest[..position].to_string()));
                rest = &rest[position..];
            }
            None => {
                spans.push(Span::Text(rest.to_string()));
                break;
            }
        }
    }
    spans
}

fn render_spans(spans: &[Span]) -> String {
    let mut out = String::new();
    for span in spans {
        match span {
            Span::Text(text) => out.push_str(&escape_inline(text)),
            Span::Code(code) => push_fontfied(&mut out, 'B', &escape_inline(code)),
            Span::Bold(text) => push_fontfied(&mut out, 'B', &escape_inline(text)),
            Span::Italic(text) => push_fontfied(&mut out, 'I', &escape_inline(text)),
            Span::Link { text } => out.push_str(&escape_inline(text)),
        }
    }
    out
}

fn push_fontfied(out: &mut String, font: char, text: &str) {
    out.push_str("\\f");
    out.push(font);
    out.push_str(text);
    out.push_str("\\fR");
}

fn escape_inline(text: &str) -> String {
    text.replace('\\', r"\\")
        .replace('-', r"\-")
        .replace('\'', r"\*(Aq")
        .replace('—', r"\(em")
        .replace('→', r"\(->")
        .replace('§', r"\(sc")
}
